-- ============================================================
-- Step 4: mml_command_sub_fields — 命令 ↔ standard_params 关联
-- 仅 LST/MOD 写；ADD/RMV 是对象操作不挂 sub_field。
-- 通过 standard_path 在 standard_params 中查 id；缺失 path 自然跳过。
-- ============================================================
INSERT INTO mml_command_sub_fields (
    id, command_id, standard_path_id, mml_code, label_i18n,
    default_selected, is_required, sort_order, access_type
)
SELECT gen_random_uuid(),
       (SELECT id FROM mml_commands WHERE command_code = 'LST DEVICE_INFO'),
       sp.id,
       'UserLabel', '{"en":"用户友好名","zh":"用户友好名"}'::jsonb,
       true, true, 0, 'RW'
